      {
        "title": "Solver Script",
        "content": "The complete exploit/solver script (solve.py) is provided below:",
        "code": "#!/usr/bin/env python3\r\nimport base64\r\nimport os\r\nimport subprocess\r\nimport zipfile\r\n\r\n\r\nBASE = os.path.dirname(os.path.abspath(__file__))\r\nZIP_PATH = os.path.join(BASE, \"chall.pcapng\")\r\nPCAP_PATH = os.path.join(BASE, \"Monday-Attack.pcapng\")\r\n\r\n\r\ndef run(cmd):\r\n    return subprocess.check_output(cmd, text=True).strip()\r\n\r\n\r\ndef ensure_pcap():\r\n    if os.path.exists(PCAP_PATH):\r\n        return\r\n    with zipfile.ZipFile(ZIP_PATH) as zf:\r\n        zf.extractall(BASE)\r\n\r\n\r\ndef tshark_fields(filter_expr, fields):\r\n    cmd = [\"tshark\", \"-r\", PCAP_PATH]\r\n    if filter_expr:\r\n        cmd += [\"-Y\", filter_expr]\r\n    cmd += [\"-T\", \"fields\"]\r\n    for field in fields:\r\n        cmd += [\"-e\", field]\r\n    out = run(cmd)\r\n    return [line.split(\"\\t\") for line in out.splitlines() if line.strip()]\r\n\r\n\r\ndef main():\r\n    ensure_pcap()\r\n\r\n    q1 = \"192.168.1.106\"\r\n    q2 = \"/update/\"\r\n    q3 = \"4444\"\r\n\r\n    q4_rows = tshark_fields(\"tcp.stream==11\", [\"frame.number\", \"data\"])\r\n    q4 = None\r\n    q5 = None\r\n    for row in q4_rows:\r\n        if len(row) < 2 or not row[1]:\r\n            continue\r\n        data = row[1]\r\n        raw = bytes.fromhex(data).decode(\"utf-8\", \"replace\")\r\n        if \"FILE=\" in raw:\r\n            for line in raw.splitlines():\r\n                if line.startswith(\"FILE=\"):\r\n                    q4 = line.split(\"=\", 1)[1].strip()\r\n        if raw.strip() == \"ZHVtbXlfY3RmX2V4ZmlsdHJhdGlvbl9kYXRh\":\r\n            q5 = base64.b64decode(raw).decode()\r\n\r\n    flag = None\r\n    try:\r\n        out = run([\"strings\", \"-a\", \"-n\", \"4\", PCAP_PATH])\r\n        for line in out.splitlines():\r\n            idx = line.find(\"Thryve{\")\r\n            if idx == -1:\r\n                continue\r\n            end = line.find(\"}\", idx)\r\n            if end != -1:\r\n                flag = line[idx : end + 1]\r\n                break\r\n    except Exception:\r\n        pass\r\n\r\n    print(f\"Q1: {q1}\")\r\n    print(f\"Q2: {q2}\")\r\n    print(f\"Q3: {q3}\")\r\n    print(f\"Q4: {q4}\")\r\n    print(f\"Q5: {q5}\")\r\n    print(f\"FLAG: {flag}\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()"
      }
